import{_ as t,o as a,c as o,a3 as r}from"./chunks/framework.BTQ4eCVb.js";const u=JSON.parse('{"title":"Knowledge Base — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Knowledge Base — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/knowledge-base"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Knowledge Base — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/knowledge-base"}]]},"headers":[],"relativePath":"user-guide/knowledge-base.md","filePath":"user-guide/knowledge-base.md","lastUpdated":1787503667000}'),i={name:"user-guide/knowledge-base.md"};function s(l,e,d,n,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="knowledge-base-—-user-guide" tabindex="-1">Knowledge Base — User Guide <a class="header-anchor" href="#knowledge-base-—-user-guide" aria-label="Permalink to &quot;Knowledge Base — User Guide&quot;">​</a></h1><p>Install <strong>Knowledge Base</strong> from Marketplace (free <strong>Operations</strong> module). Until it is installed, the Knowledge Base nav stays hidden. This module is for <strong>internal team</strong> articles only — there is no public or customer portal in v1.0.0.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><ol><li>Open <strong>Marketplace</strong></li><li>Find <strong>Knowledge Base</strong> under <strong>Operations</strong></li><li>Install (free; not included by default)</li><li>Refresh the app session if the sidebar does not update immediately</li></ol><h2 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h2><p>Requires <code>knowledge-base.create</code> (or update/delete as noted).</p><ol><li>Open <strong>Knowledge Base</strong> → manage categories</li><li>Create a category with a name (slug is generated if omitted)</li><li>Optionally set sort order and active flag</li></ol><p>Categories are <strong>flat</strong> (no nesting). You cannot delete a category while articles still use it — reassign or clear the category on those articles first.</p><h2 id="create-and-publish-an-article" tabindex="-1">Create and publish an article <a class="header-anchor" href="#create-and-publish-an-article" aria-label="Permalink to &quot;Create and publish an article&quot;">​</a></h2><p>Requires <code>knowledge-base.create</code> to create; <code>knowledge-base.update</code> to edit and change status.</p><ol><li>Click <strong>New article</strong></li><li>Enter title (required), optional slug / excerpt / category</li><li>Write the body in the TipTap editor (HTML stored on the server)</li><li>Save as <strong>Draft</strong>, or set status to <strong>Published</strong> / <strong>Archived</strong></li></ol><p>Publishing sets <code>published_at</code> when it was empty. Returning to draft clears <code>published_at</code>. There is no publish notification fan-out in v1.</p><h2 id="who-sees-what" tabindex="-1">Who sees what <a class="header-anchor" href="#who-sees-what" aria-label="Permalink to &quot;Who sees what&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role / permission</th><th>Visibility</th></tr></thead><tbody><tr><td><code>knowledge-base.view</code> only</td><td><strong>Published</strong> articles only</td></tr><tr><td>Also has <code>knowledge-base.update</code></td><td>Drafts, published, archived, and trash (with filters)</td></tr></tbody></table><h2 id="search-and-filters" tabindex="-1">Search and filters <a class="header-anchor" href="#search-and-filters" aria-label="Permalink to &quot;Search and filters&quot;">​</a></h2><p>On the articles list, search matches title, excerpt, and body. Editors with update permission can filter by status and trash (<code>with</code> / <code>only</code>). View-only users always see the published audience set.</p><h2 id="notes-and-activity" tabindex="-1">Notes and activity <a class="header-anchor" href="#notes-and-activity" aria-label="Permalink to &quot;Notes and activity&quot;">​</a></h2><p>Open an article to:</p><ul><li>Add <strong>notes</strong> (requires <code>knowledge-base.update</code>)</li><li>Review the <strong>activity</strong> timeline (created, updated, status changed, note, deleted, restored)</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Ability</th></tr></thead><tbody><tr><td><code>knowledge-base.view</code></td><td>List / open articles and categories (published-only without update)</td></tr><tr><td><code>knowledge-base.create</code></td><td>Create articles and categories</td></tr><tr><td><code>knowledge-base.update</code></td><td>Edit, publish / archive, add notes; see drafts / archived / trash</td></tr><tr><td><code>knowledge-base.delete</code></td><td>Soft delete</td></tr><tr><td><code>knowledge-base.restore</code></td><td>Restore from trash</td></tr><tr><td><code>knowledge-base.force.delete</code></td><td>Permanently delete (already soft-deleted)</td></tr></tbody></table><p>Default role map: <strong>admin</strong> gets all except <code>force.delete</code>; <strong>manager</strong> gets view / create / update; <strong>staff</strong> gets view. Workspace owners (<code>superadmin</code>) receive all permissions via provisioning.</p><h2 id="explicitly-deferred" tabindex="-1">Explicitly deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly deferred&quot;">​</a></h2><ul><li>Public URLs and customer portal</li><li>Help Desk links</li><li>Attachments / image upload</li><li>Nested categories</li><li>Dashboard widget</li><li>Automation triggers</li><li>Publish fan-out notifications</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/user-guide/knowledge-base-overview">Knowledge Base overview</a></li><li><a href="/api/tenant-v1-knowledge-base">Tenant API</a></li><li><a href="/user-guide/tenant-application#marketplace-add--remove-modules">Marketplace</a></li></ul>',26)])])}const p=t(i,[["render",s]]);export{u as __pageData,p as default};
